<section class="mn-brief" aria-label="Smart briefing" data-sl-scope><div class="mn-bh"><span class="mn-ai"><i class="ic i-ai" aria-hidden="true"></i></span><div class="col grow"><b class="fw5">Operations briefing · <?= h($d['briefLead']) ?></b><span class="mut sm">Shipments, warehouse exceptions and customer requests</span></div><a class="sl-btn ghost sm" href="<?= sl_route('StaffAI') ?>"><i class="ic ic-sm i-spark" aria-hidden="true"></i>Ask <?= h(cdp_kingName()) ?></a></div>
